public sealed class HealthEndpoints
{
    private readonly IReadinessProbe _readiness;

    public HealthEndpoints(IReadinessProbe readiness)
    {
        _readiness = readiness;
    }

    public IResult Live()
    {
        // The process can execute requests.
        return Results.Ok();
    }

    public async Task<IResult> ReadyAsync(
        CancellationToken cancellationToken)
    {
        bool canServe = await _readiness.CanServeAsync(cancellationToken);
        if (!canServe)
        {
            return Results.StatusCode(
                StatusCodes.Status503ServiceUnavailable);
        }

        return Results.Ok();
    }
}

