public sealed class SafeExceptionHandler : IExceptionHandler
{
    private readonly ILogger<SafeExceptionHandler> _logger;

    public SafeExceptionHandler(ILogger<SafeExceptionHandler> logger)
    {
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(
        HttpContext context,
        Exception exception,
        CancellationToken cancellationToken)
    {
        string traceId = Activity.Current?.TraceId.ToString()
            ?? context.TraceIdentifier;

        _logger.LogError(
            exception,
            "Unhandled request failure with trace {TraceId}",
            traceId);

        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
        ApiError response = new ApiError(
            code: "internal_error",
            message: "The request could not be completed.",
            traceId: traceId);
        await context.Response.WriteAsJsonAsync(response, cancellationToken);
        return true;
    }
}

